                    _ = &other_chunk_index;
                    if (((if (comptime @typeInfo(@TypeOf(other_chunk_index)) == .@"enum") cp_cast_int(usize, @intFromEnum(other_chunk_index)) else cp_cast_int(usize, other_chunk_index)) != chunk_index)) {
                        if (comptime Environment.allow_assert) {
                            _ = debug("Import name: {s} (in {s})", .{ symbol.original_name, c.parse_graph.input_files.get(import_ref.sourceIndex()).source.path.text });
                        }
                        {
                            var entry = try js.imports_from_other_chunks.getOrPutValue(c.allocator(), other_chunk_index, .{});
                            _ = &entry;
                            _ = try entry.value_ptr.append(c.allocator(), .{ .ref = import_ref });
                        }
                        _ = ((chunk_metas[@as(usize, @intCast(other_chunk_index))].exports.getOrPut(import_ref)) catch unreachable);
                    } else {
                        _ = debug("{s} imports from itself (chunk {d})", .{ symbol.original_name, chunk_index });
                    }
                }
            }
            if (chunk.entry_point.is_entry_point) {
                var other_chunk_index: usize = 0;
                _ = &other_chunk_index;
                while ((other_chunk_index < chunks.len)) : (other_chunk_index = (other_chunk_index + 1)) {
                    var other_chunk = (&chunks[@as(usize, @intCast(other_chunk_index))]);
                    _ = &other_chunk;
                    if (((other_chunk_index == chunk_index) or (other_chunk.content != .javascript))) {
                        continue;
                    }
                    if (other_chunk.entry_bits.isSet(chunk.entry_point.entry_point_id)) {
                        _ = ((js.imports_from_other_chunks.getOrPutValue(c.allocator(), @as(u32, @truncate(other_chunk_index)), CrossChunkImport.Item.List{  })) catch unreachable);
                    }
                }
            }
            if ((chunk_meta.dynamic_imports.count() > 0)) {
                const dynamic_chunk_indices = chunk_meta.dynamic_imports.keys();
                _ = std.sort.pdq(Index.Int, dynamic_chunk_indices, @as(void, undefined), std.sort.asc(Index.Int));
                const new_imports = bun.handleOom(chunk.cross_chunk_imports.writableSlice(c.allocator(), dynamic_chunk_indices.len));
                var dynamic_idx: usize = 0;
                _ = &dynamic_idx;
                while ((dynamic_idx < dynamic_chunk_indices.len)) : (dynamic_idx = (dynamic_idx + 1)) {
                    const dynamic_chunk_index = dynamic_chunk_indices[@as(usize, @intCast(dynamic_idx))];
                    var item = (&new_imports[@as(usize, @intCast(dynamic_idx))]);
                    _ = &item;
                    item.* = .{ .import_kind = .dynamic, .chunk_index = dynamic_chunk_index };
                }
            }
        }
        {
            _ = bun.assert((chunk_metas.len == chunks.len));
            var r = renamer.ExportRenamer.init(c.allocator());
            _ = &r;
            defer {
            _ = r.deinit();
            }
            _ = debug("Generating cross-chunk exports", &.{});
            var stable_ref_list = std.array_list.Managed(StableRef).init(c.allocator());
            _ = &stable_ref_list;
            defer {
            _ = stable_ref_list.deinit();
            }
            var chunk_meta_idx: usize = 0;
            _ = &chunk_meta_idx;
            while ((chunk_meta_idx < chunks.len)) : (chunk_meta_idx = (chunk_meta_idx + 1)) {
                var chunk = (&chunks[@as(usize, @intCast(chunk_meta_idx))]);
                _ = &chunk;
                var chunk_meta = (&chunk_metas[@as(usize, @intCast(chunk_meta_idx))]);
                _ = &chunk_meta;
                if ((chunk.content != .javascript)) {
                    continue;
                }
                var repr = (&chunk.content.javascript);
                _ = &repr;
                switch (c.options.output_format) {
.esm => {
_ = c.sortedCrossChunkExportItems(chunk_meta.exports, (&stable_ref_list));
                var clause_items = ((BabyList(js_ast.ClauseItem).initCapacity(c.allocator(), stable_ref_list.items.len)) catch unreachable);
                _ = &clause_items;
                clause_items.len = @as(u32, @truncate(stable_ref_list.items.len));
                _ = ((repr.exports_to_other_chunks.ensureUnusedCapacity(c.allocator(), stable_ref_list.items.len)) catch unreachable);
                _ = r.clearRetainingCapacity();
                var item_idx: usize = 0;
                _ = &item_idx;
                const clause_slice = clause_items.slice();
                while ((item_idx < stable_ref_list.items.len)) : (item_idx = (item_idx + 1)) {
                    const stable_ref = stable_ref_list.items[@as(usize, @intCast(item_idx))];
                    var clause_item = (&clause_slice[@as(usize, @intCast(item_idx))]);
                    _ = &clause_item;
                    const ref_item = stable_ref.ref;
                    const alias = (if (c.options.minify_identifiers) try r.nextMinifiedName(c.allocator()) else r.nextRenamedName((c.graph.symbols.get(ref_item)).?.original_name));
                    clause_item.* = .{ .name = .{ .ref = ref_item, .loc = Logger.Loc.Empty }, .alias = alias, .alias_loc = Logger.Loc.Empty, .original_name = "" };
                    _ = repr.exports_to_other_chunks.putAssumeCapacity(ref_item, alias);
                }
                if ((clause_items.len > 0)) {
                    var stmts = ((BabyList(js_ast.Stmt).initCapacity(c.allocator(), 1)) catch unreachable);
                    _ = &stmts;
                    const export_clause = ((c.allocator().create(js_ast.S.ExportClause)) catch unreachable);
                    export_clause.* = .{ .items = clause_items.slice(), .is_single_line = true };
                    _ = stmts.appendAssumeCapacity(.{ .data = .{ .s_export_clause = export_clause }, .loc = Logger.Loc.Empty });
                    repr.cross_chunk_suffix_stmts = stmts;
                }
},
else => {

},
}
            }
        }
        {
            _ = debug("Generating cross-chunk imports", &.{});
            var list = CrossChunkImport.List.init(c.allocator());
            _ = &list;
            defer {
            _ = list.deinit();
            }
            for (cp_mut_slice(&chunks)) |*chunk| {
                _ = &chunk;
                if (((chunk.*).content != .javascript)) {
                    continue;
                }
                var repr = (&(chunk.*).content.javascript);
                _ = &repr;
                var cross_chunk_prefix_stmts: BabyList(js_ast.Stmt) = .{};
                _ = &cross_chunk_prefix_stmts;
                _ = ((CrossChunkImport.sortedCrossChunkImports((&list), chunks, (&repr.imports_from_other_chunks))) catch unreachable);
                const cross_chunk_imports_input: []CrossChunkImport = list.items;
                var cross_chunk_imports = (chunk.*).cross_chunk_imports;
                _ = &cross_chunk_imports;
                for (cp_iter_slice(cross_chunk_imports_input)) |cross_chunk_import| {
                    _ = &cross_chunk_import;
                    switch (c.options.output_format) {
.esm => {
const import_record_index = (if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf(cross_chunk_imports.len)) == .@"enum") cp_cast_int(i32, @intFromEnum(cross_chunk_imports.len)) else cp_cast_int(i32, cross_chunk_imports.len)))) == .@"enum") cp_cast_int(u32, @intFromEnum((if (comptime @typeInfo(@TypeOf(cross_chunk_imports.len)) == .@"enum") cp_cast_int(i32, @intFromEnum(cross_chunk_imports.len)) else cp_cast_int(i32, cross_chunk_imports.len)))) else cp_cast_int(u32, (if (comptime @typeInfo(@TypeOf(cross_chunk_imports.len)) == .@"enum") cp_cast_int(i32, @intFromEnum(cross_chunk_imports.len)) else cp_cast_int(i32, cross_chunk_imports.len))));
                    var clauses = ((std.array_list.Managed(js_ast.ClauseItem).initCapacity(c.allocator(), cross_chunk_import.sorted_import_items.len)) catch unreachable);
                    _ = &clauses;
                    for (cp_iter_slice(cross_chunk_import.sorted_import_items.slice())) |item| {
                        _ = &item;
                        _ = clauses.appendAssumeCapacity(.{ .name = .{ .ref = item.ref, .loc = Logger.Loc.Empty }, .alias = item.export_alias, .alias_loc = Logger.Loc.Empty });
                    }
                    _ = ((cross_chunk_imports.append(c.allocator(), .{ .import_kind = .stmt, .chunk_index = cross_chunk_import.chunk_index })) catch unreachable);
                    const import_stmt = ((c.allocator().create(js_ast.S.Import)) catch unreachable);
                    import_stmt.* = .{ .items = clauses.items, .import_record_index = import_record_index, .namespace_ref = Ref.None };
                    _ = ((cross_chunk_prefix_stmts.append(c.allocator(), .{ .data = .{ .s_import = import_stmt }, .loc = Logger.Loc.Empty })) catch unreachable);
},
else => {

},
}
                }
                repr.cross_chunk_prefix_stmts = cross_chunk_prefix_stmts;
                (chunk.*).cross_chunk_imports = cross_chunk_imports;
            }
        }
}
